function renderMaint(s,c){const r=getCollection('reportes');if(s==='inicio'){setHeader('Inicio');c.innerHTML=statCards([['Pendientes',r.filter(x=>x.estado==='PENDIENTE').length],['En revisión',r.filter(x=>x.estado==='EN_REVISION').length],['En proceso',r.filter(x=>x.estado==='EN_PROCESO').length],['Resueltos',r.filter(x=>x.estado==='RESUELTO').length]])+`<div class="section-head"><h2>Reportes recientes</h2></div><div class="card">${r.slice().reverse().slice(0,5).map(maintRow).join('')}</div>`}else if(s==='reportes'){setHeader('Reportes');c.innerHTML=`<div class="section-head"><h2>Gestión de reportes</h2></div><div class="card">${r.map(maintRow).join('')}</div>`}}
function maintRow(r){return `<div class="report-row"><div><strong>#${escapeHTML(r.id)} · ${escapeHTML(r.ubicacion)}</strong><small class="muted">${escapeHTML(r.descripcion)} · ${r.fecha}</small></div><div><select onchange="changeReport('${r.id}',this.value)">${['PENDIENTE','EN_REVISION','EN_PROCESO','RESUELTO'].map(s=>`<option ${s===r.estado?'selected':''}>${s}</option>`).join('')}</select></div></div>`}
function changeReport(id,status){const a=getCollection('reportes'),r=a.find(x=>x.id===id);if(r){r.estado=status;r.comentarios=r.comentarios||[];r.comentarios.push('Estado actualizado a '+status+' por mantenimiento.')}saveCollection('reportes',a);render('reportes');showToast('Estado actualizado')}